package com.oms.supplychain.service.wms;

import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import com.ruoyi.common.core.domain.R;
import com.oms.common.model.dto.wms.WmsInventoryBatchDto;
import org.mockito.ArgumentCaptor;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

class SharedReturnParcelsTest {
    ExchangeReturnTest f;SharedReturnParcels parcels;RefundReturnService refunds;long parcel,exchangeMember,refundMember,refundTask,document;
    @BeforeEach void setup(){
        f=new ExchangeReturnTest();f.setup();for(String t:Arrays.asList("wms_shared_return_receipt","wms_shared_return_document","wms_shared_return_member","wms_shared_return_parcel","wms_refund_return_line","wms_refund_return_event","wms_refund_return_review","wms_refund_return"))f.jdbc.update("DELETE FROM "+t);
        refunds=new RefundReturnService();ReflectionTestUtils.setField(refunds,"db",f.db);ReflectionTestUtils.setField(refunds,"store",f.db);ReflectionTestUtils.setField(refunds,"inventory",f.inventory);ReflectionTestUtils.setField(refunds,"logs",mock(WmsInteractionLog.class));
        parcel=f.db.insert("wms_shared_return_parcel",map("company_code","QM","parcel_sn","ASP_TEST","channel_id",10,"platform_tid","123456","carrier_code","SF","waybill","TEST_SHARED_01","store_code","V1","connection_id",1,"external_owner","EXT-O","external_warehouse","EXT-W","owner_code","O","real_store_code","W","dispatch_after",new java.sql.Timestamp(System.currentTimeMillis()+120000)));
        refundTask=f.db.insert("wms_refund_return",map("company_code","QM","plan_id",2,"refund_id",20,"return_sn","RSL_REFUND","refund_sn","TK_TEST","order_sn","SO_TEST","platform_tid","123456","original_shipment_sn","XS_OTHER","store_code","V1","sku_sn","G","quantity",3,"unit_cost","3.75","connection_id",1,"external_owner","EXT-O","external_warehouse","EXT-W","owner_code","O","real_store_code","W","payload_hash","refund_hash"));
        exchangeMember=member("EXCHANGE",1,1,id(f.task.get("id")),"A",5,"HH_TEST");refundMember=member("REFUND",20,2,refundTask,"G",3,"TK_TEST");
        document=f.db.insert("wms_shared_return_document",map("company_code","QM","parcel_id",parcel,"return_sn","THKX_TEST","quantity",8,"payload","[]","dispatch_state","ACCEPTED","external_order","WH_SHARED"));
        for(String table:Arrays.asList("wms_exchange_return","wms_refund_return"))f.jdbc.update("UPDATE "+table+" SET dispatch_state='ACCEPTED',external_order='WH_SHARED'");
        parcels=new SharedReturnParcels();parcels.db=f.db;parcels.exchanges=f.service;parcels.refunds=refunds;parcels.documents=mock(SharedReturnDocuments.class);parcels.authorization=mock(SharedReturnAuthorizationClient.class);when(parcels.authorization.context(anyString(),anyList(),anyString())).thenAnswer(a->{List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> m:(List<Map<String,Object>>)a.getArgument(1))result.add(map("member_id",m.get("id"),"active",true,"dispatch",true,"allocate",true,"mixed",true,"revision",1));return R.ok(map("members",result));});
    }
    long member(String kind,long owner,long source,long task,String sku,long qty,String sn){long id=f.db.insert("wms_shared_return_member",map("company_code","QM","parcel_id",parcel,"owner_kind",kind,"owner_id",owner,"owner_sn",sn,"source_id",source,"task_id",task,"order_sn","SO_TEST","platform_oid","123457","sku_sn",sku,"quantity",qty,"source_hash",kind.equals("EXCHANGE")?"hash":"refund_hash","mixed_allowed",1,"dispatch_allowed",1,"allocate_allowed",1,"policy_revision",1));f.jdbc.update("UPDATE "+SharedReturnParcels.table(kind)+" SET shared_member_id=? WHERE id=?",id,task);return id;}
    WmsProtocol.Line line(String sku,String no,int good,int bad){WmsProtocol.Line line=new WmsProtocol.Line();line.sku=sku;line.lineNo=no;line.owner="EXT-O";line.batch="ORIGINAL-RETURN";line.good=good;line.bad=bad;return line;}
    long receipt(boolean complete,WmsProtocol.Line... lines){WmsProtocol.Receipt r=new WmsProtocol.Receipt();r.messageId="SHARED-"+UUID.randomUUID();r.ticketSn="THKX_TEST";r.externalOrder="WH_SHARED";r.owner="EXT-O";r.warehouse="EXT-W";r.complete=complete;r.status=complete?"FULFILLED":"PARTFULFILLED";r.lines=Arrays.asList(lines);r.sourceLineCount=lines.length;return f.db.insert("wms_shared_return_receipt",map("company_code","QM","parcel_id",parcel,"document_id",document,"message_id",r.messageId,"payload_hash",QimenProtocol.hash("SHA-256",f.db.encode(r)),"payload",f.db.encode(r),"source_log_id",1));}
    long posted(String kind){return f.jdbc.queryForObject("SELECT COALESCE(SUM(posted_quantity),0) FROM "+SharedReturnParcels.table(kind),Long.class);}
    Map<String,Object> manual(long event,List<Map<String,Object>> assignments){return map("parcel_version",f.db.one("SELECT control_version FROM wms_shared_return_parcel WHERE id=?",parcel).get("control_version"),"confirmed",true,"reason","warehouse source checked","evidence","TEST-SOURCE-EVIDENCE","actor","tester","allocations",assignments);}
    @Test void mixedSourcesPostToTheirOwnLedgerOnceWithOriginalCosts(){long event=receipt(true,line("A",String.valueOf(exchangeMember),5,0),line("G",String.valueOf(refundMember),3,0));parcels.allocate("QM",parcel,event,Collections.emptyMap(),true);parcels.allocate("QM",parcel,event,Collections.emptyMap(),true);assertEquals(5,posted("EXCHANGE"));assertEquals(3,posted("REFUND"));ArgumentCaptor<WmsInventoryBatchDto> calls=ArgumentCaptor.forClass(WmsInventoryBatchDto.class);verify(f.inventory,times(2)).addInventory(calls.capture(),eq("QM"));Set<String> refs=new HashSet<>();Set<java.math.BigDecimal> costs=new HashSet<>();for(WmsInventoryBatchDto call:calls.getAllValues()){refs.add(call.getRelationSn().substring(0,call.getRelationSn().indexOf("RETURN")+6));costs.add(call.getWmsInventoryBatch().getTransactionPrice().stripTrailingZeros());}assertEquals(2,refs.size());assertTrue(costs.contains(new java.math.BigDecimal("2.5")));assertTrue(costs.contains(new java.math.BigDecimal("3.75")));}
    @Test void sameSkuWithoutLineNumberStaysPendingAndDoesNotIncreaseStock(){f.jdbc.update("UPDATE wms_refund_return SET sku_sn='A'");f.jdbc.update("UPDATE wms_shared_return_member SET sku_sn='A' WHERE id=?",refundMember);long event=receipt(true,line("A","",8,0));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,Collections.emptyMap(),true));assertEquals(0,posted("EXCHANGE"));assertEquals(0,posted("REFUND"));verifyNoInteractions(f.inventory);}
    @Test void manualSameSkuAllocationUsesExplicitMemberIdentity(){f.jdbc.update("UPDATE wms_refund_return SET sku_sn='A'");f.jdbc.update("UPDATE wms_shared_return_member SET sku_sn='A' WHERE id=?",refundMember);long event=receipt(true,line("A","",8,0));List<Map<String,Object>> split=Arrays.asList(map("line_index",0,"member_id",exchangeMember,"good_qty",5,"bad_qty",0),map("line_index",0,"member_id",refundMember,"good_qty",3,"bad_qty",0));parcels.allocate("QM",parcel,event,manual(event,split),false);assertEquals(5,posted("EXCHANGE"));assertEquals(3,posted("REFUND"));assertEquals("MANUAL",f.jdbc.queryForObject("SELECT allocation_method FROM wms_shared_return_receipt WHERE id=?",String.class,event));}
    @Test void allLineGradesMustConserveBeforeAnySourceIsAccepted(){long event=receipt(true,line("A",String.valueOf(exchangeMember),4,1),line("G",String.valueOf(refundMember),3,0));List<Map<String,Object>> wrong=Arrays.asList(map("line_index",0,"member_id",exchangeMember,"good_qty",5,"bad_qty",0),map("line_index",1,"member_id",refundMember,"good_qty",3,"bad_qty",0));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,manual(event,wrong),false));assertEquals(0,posted("EXCHANGE"));verifyNoInteractions(f.inventory);}
    @Test void finalShortReceiptRetainsCompletePlanAndNoAutomaticStock(){long event=receipt(true,line("A",String.valueOf(exchangeMember),4,0),line("G",String.valueOf(refundMember),3,0));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,Collections.emptyMap(),true));assertEquals(0,posted("EXCHANGE"));assertEquals(0,posted("REFUND"));assertEquals(5,id(f.db.one("SELECT quantity FROM wms_exchange_return").get("quantity")));}
    @Test void excessOnOneSourceRollsBackAllOtherSourceChanges(){long event=receipt(true,line("A",String.valueOf(exchangeMember),5,0),line("G",String.valueOf(refundMember),4,0));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,Collections.emptyMap(),true));assertEquals(0,posted("EXCHANGE"));assertEquals(0L,f.jdbc.queryForObject("SELECT accepted_quantity FROM wms_exchange_return",Long.class));verifyNoInteractions(f.inventory);}
    @Test void partialNonFinalReceiptPostsOnlyReceivedQuantityAndDoesNotComplete(){long event=receipt(false,line("A",String.valueOf(exchangeMember),2,0));parcels.allocate("QM",parcel,event,Collections.emptyMap(),true);assertEquals(2,posted("EXCHANGE"));assertEquals(0,posted("REFUND"));assertEquals("PARTIAL",f.db.one("SELECT receipt_state FROM wms_exchange_return").get("receipt_state"));}
    @Test void wrongSkuCannotBeAssignedEvenWithManualConfirmation(){long event=receipt(false,line("OTHER",String.valueOf(exchangeMember),1,0));List<Map<String,Object>> split=Collections.singletonList(map("line_index",0,"member_id",exchangeMember,"good_qty",1,"bad_qty",0));assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,manual(event,split),false));verifyNoInteractions(f.inventory);}
    @Test void staleParcelVersionCannotAllocateIntoUpdatedScope(){long event=receipt(true,line("A",String.valueOf(exchangeMember),5,0),line("G",String.valueOf(refundMember),3,0));Map<String,Object> request=manual(event,Collections.emptyList());f.jdbc.update("UPDATE wms_shared_return_parcel SET control_version=control_version+1 WHERE id=?",parcel);assertThrows(IllegalArgumentException.class,()->parcels.allocate("QM",parcel,event,request,false));verifyNoInteractions(f.inventory);}
    @Test void disabledCurrentAuthorizationRetainsReceiptWithoutPosting(){receipt(true,line("A",String.valueOf(exchangeMember),5,0),line("G",String.valueOf(refundMember),3,0));when(parcels.authorization.context(anyString(),anyList(),anyString())).thenReturn(R.ok(map("members",Arrays.asList(map("member_id",exchangeMember,"active",true,"allocate",false),map("member_id",refundMember,"active",true,"allocate",true)))));parcels.reconcile("QM",parcel);assertEquals(0,posted("EXCHANGE"));assertEquals("WAIT_ALLOCATION",f.jdbc.queryForObject("SELECT state FROM wms_shared_return_receipt",String.class));verifyNoInteractions(f.inventory);}
    @Test void confirmedLateReceiptCanBeManuallyAttributedWithoutUndoingCancellation(){f.jdbc.update("UPDATE wms_shared_return_document SET cancel_state='CONFIRMED'");f.jdbc.update("UPDATE wms_exchange_return SET cancel_state='CONFIRMED',cancelled_quantity=quantity");f.jdbc.update("UPDATE wms_refund_return SET cancel_state='CONFIRMED',cancelled_quantity=quantity");long event=receipt(false,line("A",String.valueOf(exchangeMember),2,0));List<Map<String,Object>> assignment=Collections.singletonList(map("line_index",0,"member_id",exchangeMember,"good_qty",2,"bad_qty",0));parcels.allocate("QM",parcel,event,manual(event,assignment),false);assertEquals(2,posted("EXCHANGE"));assertEquals(0,posted("REFUND"));assertEquals(5L,f.jdbc.queryForObject("SELECT cancelled_quantity FROM wms_exchange_return",Long.class));assertEquals("CANCELED",f.jdbc.queryForObject("SELECT dispatch_state FROM wms_exchange_return",String.class));}
    @Test void rejectingAnInvalidReceiptPreservesOriginalEvidenceAndDoesNotPostStock(){long event=receipt(false,line("OTHER","",2,0));Map<String,Object> input=manual(event,Collections.emptyList());input.put("confirmed_shared",true);input.put("receipt_id",event);parcels.reject("QM",parcel,input);assertEquals("REJECTED",f.jdbc.queryForObject("SELECT state FROM wms_shared_return_receipt WHERE id=?",String.class,event));assertTrue(f.jdbc.queryForObject("SELECT allocation_json FROM wms_shared_return_receipt WHERE id=?",String.class,event).contains("TEST-SOURCE-EVIDENCE"));assertEquals(0,posted("EXCHANGE"));verifyNoInteractions(f.inventory);}
    @Test void commonWarehouseWireUsesReturnTypeAndUniqueMemberLineNumbers(){Map<String,Object> connection=map("provider","QIMEN","api_version","2.0","endpoint","http://test","app_key","test","customer_id","test");Map<String,Object> wire=map("business_type","AFTERSALE_IN","return_sn","THKX_TEST","external_owner","EXT-O","external_warehouse","EXT-W","create_time","2026-10-24 12:00:00","order_lines",Arrays.asList(map("line_no",exchangeMember,"sku_sn","A","quantity",5),map("line_no",refundMember,"sku_sn","G","quantity",3)));String body=f.protocol.request(connection,"test-secret","CREATE",wire).body;assertTrue(body.contains("<orderType>THRK</orderType>"));assertTrue(body.contains("<orderLineNo>"+exchangeMember+"</orderLineNo>"));assertTrue(body.contains("<orderLineNo>"+refundMember+"</orderLineNo>"));}
}
